toolCall.argumentsJson:
{"CommandLine":"powershell -Command "
Get-ChildItem C:\ -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    `$folder = `$_.FullName
    try {
        `$size = (Get-ChildItem `$folder -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        [PSCustomObject]@{
            Folder = `$folder
            SizeGB = [math]::Round(`$size / 1GB, 2)
        }
    } catch {}
} | Sort-Object SizeGB -Descending | Select-Object -First 10
"","Cwd":"C:\AI-BS","WaitMsBeforeAsync":15000,"toolAction":"Measure top-level folders on C:","toolSummary":"Measure C: drive folders"}
